import{_ as t,o,c as e,aj as r}from"./chunks/framework.kB0W2StX.js";const p=JSON.parse('{"title":"Специалист по работе с клиентами / Риелтор новостроек","description":"","frontmatter":{},"headers":[],"relativePath":"data/ai-construction-part12.md","filePath":"data/ai-construction-part12.md"}'),i={name:"data/ai-construction-part12.md"};function l(n,a,s,c,d,u){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="специалист-по-работе-с-клиентами-риелтор-новостроек" tabindex="-1">Специалист по работе с клиентами / Риелтор новостроек <a class="header-anchor" href="#специалист-по-работе-с-клиентами-риелтор-новостроек" aria-label="Permalink to &quot;Специалист по работе с клиентами / Риелтор новостроек&quot;">​</a></h1><p>В эпоху цифровой трансформации продажи в недвижимости переходят от стандартных буклетов к интерактивному клиентскому опыту. Искусственный интеллект становится главным инструментом для персонализации предложений, позволяя визуализировать будущее жилье под конкретные запросы покупателя и автоматизировать рутинные этапы ведения сделки.</p><div class="info custom-block"><p class="custom-block-title">Роль и задачи в современности</p><p>Специалист отдела продаж девелопера использует ИИ для создания индивидуальных презентаций квартир, моментальной генерации 3D-туров из обычных планировок и автоматизации первичного общения с клиентами через умных чат-ботов.</p></div><h2 id="рекомендуемые-ии-инструменты" tabindex="-1">Рекомендуемые ИИ-инструменты <a class="header-anchor" href="#рекомендуемые-ии-инструменты" aria-label="Permalink to &quot;Рекомендуемые ИИ-инструменты&quot;">​</a></h2><p>Для автоматизации взаимодействия с покупателями и создания эффектного визуального контента сформировался следующий ИИ-стек:</p><ul><li><strong>Planner 5D / Homestyler</strong> — планировщики интерьеров с ИИ, которые создают фотореалистичный дизайн-проект квартиры по одной фотографии чертежа за 5 минут.</li><li><strong>Midjourney / Magnific AI</strong> — нейросети для апскейла и улучшения качества рендеров, проработки видов из окон ЖК и детальной визуализации коммерческих помещений.</li><li><strong>ManyChat / Chatfuel с интеграцией OpenAI</strong> — умные диалоговые роботы для круглосуточной квалификации лидов, ответов на вопросы о стоимости квадратного метра и записи на просмотр 24/7.</li></ul><hr><h2 id="в-чем-конкретно-помогает-ии" tabindex="-1">В чем конкретно помогает ИИ <a class="header-anchor" href="#в-чем-конкретно-помогает-ии" aria-label="Permalink to &quot;В чем конкретно помогает ИИ&quot;">​</a></h2><p>Интеграция искусственного интеллекта в работу коммерческого блока позволяет повысить конверсию в сделку и сократить цикл продаж:</p><ol><li><strong>Мгновенная визуализация для клиента</strong> Помогает покупателю «голой» квартиры в бетоне сразу увидеть на экране планшета 3-4 варианта готовой отделки и расстановки мебели именно под его стиль жизни.</li><li><strong>Автоматический консалтинг</strong> ИИ-бот на сайте мгновенно отвечает на сложные вопросы клиентов о доступных банках по семейной ипотеке, условиях эскроу-счетов и проектной декларации.</li><li><strong>Персонализация предложений</strong> Автоматически анализирует анкету клиента и формирует PDF-презентацию с акцентом на важные для него вещи (для семейных — детские сады рядом, для инвесторов — доходность).</li></ol><hr><h2 id="практические-промты-для-работы" tabindex="-1">Практические промты для работы <a class="header-anchor" href="#практические-промты-для-работы" aria-label="Permalink to &quot;Практические промты для работы&quot;">​</a></h2><p>Вы можете использовать эти проверенные шаблоны запросов для автоматизации инженерных задач и работы с документацией.</p><h3 id="_1-промт-для-генерации-рекламного-описания-планировки" tabindex="-1">1. Промт для генерации рекламного описания планировки <a class="header-anchor" href="#_1-промт-для-генерации-рекламного-описания-планировки" aria-label="Permalink to &quot;1. Промт для генерации рекламного описания планировки&quot;">​</a></h3><blockquote><p><code>«Действуй как элитный брокер по недвижимости. Напиши продающий, эмоциональный, но без лишней &quot;воды&quot; текст для описания евро-трехкомнатной квартиры (72 кв.м) с мастер-спальней, гардеробной и панорамными окнами на реку в ЖК бизнес-класса &quot;Ривер Парк&quot;. Целевая аудитория: молодая семья с ребенком. Выдели преимущества планировки для их повседневного комфорта».</code></p></blockquote><h3 id="_2-промт-для-отработки-возражения-по-цене" tabindex="-1">2. Промт для отработки возражения по цене <a class="header-anchor" href="#_2-промт-для-отработки-возражения-по-цене" aria-label="Permalink to &quot;2. Промт для отработки возражения по цене&quot;">​</a></h3><blockquote><p><code>«Клиент пишет: &quot;Ваш жилой комплекс слишком дорогой, в 15 минутах езды от вас есть ЖК от другого застройщика, где квадратный метр стоит на 20% дешевле&quot;. Напиши вежливый, убедительный ответ менеджера по продажам. Сделай упор на закрытый двор без машин, собственную школу во дворе, использование премиального кирпича вместо панелей и более высокую ликвидность объекта в будущем».</code></p></blockquote>',17)])])}const _=t(i,[["render",l]]);export{p as __pageData,_ as default};
